-- Apply once to a durable PostgreSQL database. All timestamps are UTC timestamptz.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_expiry ON sessions(user_id,expires_at);
CREATE TABLE IF NOT EXISTS social_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, platform text NOT NULL CHECK(platform IN ('telegram','bale','instagram')), name text NOT NULL, account_id text NOT NULL, encrypted_credentials text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS connections_user ON social_connections(user_id);
CREATE TABLE IF NOT EXISTS rss_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, name text NOT NULL, url text NOT NULL, enabled boolean NOT NULL DEFAULT true, options jsonb NOT NULL DEFAULT '{}'::jsonb, next_check_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,url));
CREATE TABLE IF NOT EXISTS content_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, source_id uuid REFERENCES rss_sources(id) ON DELETE SET NULL, external_guid text, title text NOT NULL, body text NOT NULL, source_url text, image_url text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS content_source_guid ON content_items(source_id,external_guid) WHERE source_id IS NOT NULL AND external_guid IS NOT NULL;
CREATE TABLE IF NOT EXISTS publish_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, content_id uuid NOT NULL REFERENCES content_items(id), connection_id uuid NOT NULL REFERENCES social_connections(id), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','ready','scheduled','publishing','published','failed','cancelled','review')), due_at timestamptz, locked_until timestamptz, attempt_count integer NOT NULL DEFAULT 0, idempotency_key text NOT NULL UNIQUE, remote_message_id text, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS publish_due ON publish_jobs(status,due_at) WHERE status IN ('ready','scheduled');
CREATE TABLE IF NOT EXISTS audit_events (id bigserial PRIMARY KEY, user_id uuid REFERENCES app_users(id) ON DELETE SET NULL, action text NOT NULL, subject_id text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
